	static String file = System.getProperty("harness.file", "");

	@Override public DirectoryRunner.Compiler getCompiler() {
		return DirectoryRunner.Compiler.DELOMBOK;
	}

	@Override public boolean printErrors() {
		return true;
	}

	@Override public File getBeforeDirectory() {
		return new File("test/pretty/resource/before");
	}

	@Override public File getAfterDirectory() {
		return new File("test/pretty/resource/after");
	}

	@Override public File getMessagesDirectory() {
		return new File("test/pretty/resource/messages");
	}

	@Override public boolean expectChanges() {
		return false;
	}

	@Override public String testNamePrefix() {
		return "prettyprint-";
	}

	@Override public boolean accept(File f) {
		if (file.isEmpty()) return true;
		for (String s : file.split(",")) {
			if (f.getName().equals(s.trim())) return true;
		}
		return false;
	}
}

